// Watches a review queue and wakes the review chat only when something new needs a reviewer.
import { execFile } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const run = (cmd, args, signal) => new Promise((resolve, reject) => {
  execFile(cmd, args, { signal, timeout: 240000, windowsHide: true },
    (err, stdout, stderr) => (err ? reject(new Error(`${cmd} failed: ${err.message}
${String(stderr).slice(-1500)}`)) : resolve(stdout)));
});

function inUkWorkingTime(from, to) {
  const parts = Object.fromEntries(new Intl.DateTimeFormat("en-GB", {
    timeZone: "Europe/London", weekday: "short", hour: "2-digit", hour12: false,
  }).formatToParts(new Date()).map((p) => [p.type, p.value]));
  const hour = Number(parts.hour) % 24;
  return !["Sat", "Sun"].includes(parts.weekday) && hour >= from && hour < to;
}

export default async function main(ctx) {
  const { python, scriptPath, days, sessionId, fromHour, toHour, queueJson } = ctx.inputs;
  if (!queueJson && !inUkWorkingTime(Number(fromHour || 8), Number(toHour || 19))) return;
  let data;
  if (queueJson) data = JSON.parse(readFileSync(queueJson, "utf8"));
  else {
    const dir = mkdtempSync(join(tmpdir(), "review-queue-"));
    try {
      const out = join(dir, "queue.json");
      await run(python || "python", [scriptPath, "--days", String(days || 3), "--json", out], ctx.signal);
      data = JSON.parse(readFileSync(out, "utf8"));
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  }
  const seen = new Set(ctx.state.seen ?? []);
  const fresh = (data.queue ?? []).filter((p) => !seen.has(`${p.repo}#${p.pr}@${p.head}`));
  ctx.state = { seen: (data.queue ?? []).map((p) => `${p.repo}#${p.pr}@${p.head}`) };
  if (!fresh.length) return ctx.log("no change");
  const res = await ctx.ai.chat("review-queue", `Review-queue watch: ${fresh.length} item(s) new.`, { sessionId, wait: false });
  if (!res.ok && !res.busy) throw new Error(`could not reach the review chat: ${res.error ?? "unknown error"}`);
}
